#include "../src/runtime_asset.h"
#include "../src/world_asset.h"
#include "../src/traffic_scene.h"
#include "../src/traffic_grid.h"
#include "../src/traffic_init.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
typedef struct {unsigned setting,count,timer,counter,near,voice,combo_flag,sound,active,preserve_y;int delta,frame,px,py,pz,heading,speed,cx,cy,cz,cooldown,combo_whole,combo_fraction;uint32_t rng;} Config;
static void read_exact(const char *path,void *dst,size_t n){FILE *f=fopen(path,"rb");assert(f);assert(fread(dst,1,n,f)==n);assert(fclose(f)==0);}
static Config read_config(const char *path){Config c={0};FILE *f=fopen(path,"r");assert(f);assert(fscanf(f,"%u %u %u %u %u %u %u %u %u %u %d %d %d %d %d %d %d %d %d %d %d %d %d %u",&c.setting,&c.count,&c.timer,&c.counter,&c.near,&c.voice,&c.combo_flag,&c.sound,&c.active,&c.preserve_y,&c.delta,&c.frame,&c.px,&c.py,&c.pz,&c.heading,&c.speed,&c.cx,&c.cy,&c.cz,&c.cooldown,&c.combo_whole,&c.combo_fraction,&c.rng)==24);assert(fclose(f)==0);return c;}
static void load_actor(const int32_t *v,TaxiTrafficActor *a){memset(a,0,sizeof(*a));a->flags=(uint32_t)v[0];a->type=(uint32_t)v[1];a->countdown=v[2];a->x=v[3];a->y=v[4];a->z=v[5];a->heading=v[6];a->route=(uint32_t)v[7];a->path.distance=v[8];a->path.segment=(size_t)(uint32_t)v[9];a->path.x=v[10];a->path.z=v[11];a->path.heading=(uint16_t)v[12];a->impulse_x=v[13];a->impulse_z=v[14];a->offset_x=v[15];a->offset_z=v[16];a->collision_timer=v[17];}
static void apply_driver_state(TaxiTrafficScene *s,TaxiAcceleration *player,const TaxiRuntimeAsset *runtime,const Config *c){unsigned h=((uint32_t)c->heading>>12)&4095u;player->gears.speed_544=c->speed;s->player_position=(TaxiPoint){c->px,c->py,c->pz};s->camera=(TaxiPoint){c->cx,c->cy,c->cz};s->player_sine=runtime->trig.sine[h];s->player_cosine=runtime->trig.cosine[h];s->frame_delta=c->frame;s->global_delta=c->delta;s->sound_enabled=(int)c->sound;s->trip_active=(int)c->active;s->preserve_query_y=(int)c->preserve_y;s->spacing=taxi_traffic_spacing((uint8_t)c->setting);}
static void print_state(unsigned frame,int spawned,unsigned count,uint8_t timer,uint32_t counter,const TaxiTrafficGlobals *g,uint32_t rng,const TaxiAcceleration *p,const TaxiTrafficActor *actors){printf("F %u %d %u %u %u %d %u %u %u %d %d %u %d\n",frame,spawned,count,timer,counter,g->cooldown_e4,g->near_miss_25d3,g->voice_25d6,g->combo_flag_9aa6,g->combo_9aa8,g->combo_9aac,rng,p->gears.speed_544);for(unsigned i=0;i<50;i++){const TaxiTrafficActor *a=actors+i;printf("A %u %u %u %d %d %d %d %d %u %d %d %d %d %d %d %llu %d %d %u\n",i,a->flags,a->type,a->countdown,a->x,a->y,a->z,a->heading,a->route,a->collision_timer,a->impulse_x,a->impulse_z,a->offset_x,a->offset_z,a->path.distance,(unsigned long long)a->path.segment,a->path.x,a->path.z,(unsigned)a->path.heading);}}
int main(int argc,char **argv){assert(argc==4);int32_t disk[50][18];read_exact(argv[1],disk,sizeof(disk));TaxiTrafficActor actors[50]={0};for(unsigned i=0;i<50;i++)load_actor(disk[i],actors+i);Config first=read_config(argv[2]),second=read_config(argv[3]);
 TaxiRuntimeAsset runtime;assert(!taxi_runtime_asset_load(&runtime,"outputs/crazy-taxi-native/assets/driving.ctr"));TaxiWorldAsset world={0};assert(!taxi_world_asset_load(&world,"outputs/crazy-taxi-native/assets/city1.ctw"));assert(!taxi_world_asset_load_special(&world,"outputs/crazy-taxi-native/assets/city1-special.cts"));TaxiTrafficGrid grid={0};assert(!taxi_traffic_grid_load(&grid,"outputs/crazy-taxi-native/assets/traffic/city1-grid.ctg"));TaxiAiPathAsset roads[256]={0};char path[256];for(unsigned i=1;i<256;i++){snprintf(path,sizeof(path),"outputs/crazy-taxi-native/assets/traffic/city1-road-%03u.ctrp",i);FILE *f=fopen(path,"rb");if(f){fclose(f);assert(!taxi_traffic_path_load(roads+i,path));}}
 TaxiAcceleration player={0};player.gears.speed_544=first.speed;TaxiTrafficGlobals globals={.cooldown_e4=(int16_t)first.cooldown,.near_miss_25d3=(uint8_t)first.near,.voice_25d6=(uint8_t)first.voice,.combo_flag_9aa6=(uint8_t)first.combo_flag,.combo_9aa8=first.combo_whole,.combo_9aac=first.combo_fraction};uint8_t timer=(uint8_t)first.timer;uint32_t rng=first.rng,counter=first.counter;TaxiTrafficSubmission submissions[50]={0};uint32_t scales[4]={4096,4096,4096,4096};TaxiTrafficScene scene={.player=&player,.grid=&grid,.roads=roads,.trig=&runtime.trig,.angles=&runtime.traction,.globals=&globals,.timer_25d5=&timer,.rng=&rng,.selection_counter=&counter,.scales=scales,.obstacle=taxi_world_asset_obstacle,.height=taxi_world_asset_height,.terrain=&world,.submissions=submissions,.submission_count=50};apply_driver_state(&scene,&player,&runtime,&first);int spawned=taxi_traffic_scene_update(actors,first.count,&scene);print_state(0,spawned,first.count,timer,counter,&globals,rng,&player,actors);
 /* No actor, RNG or global state is reloaded here. Check the carried state is the next clean source seed. */
 assert(first.count==second.count&&first.setting==second.setting);assert(timer==(uint8_t)second.timer&&counter==second.counter&&rng==second.rng);assert(globals.cooldown_e4==(int16_t)second.cooldown&&globals.near_miss_25d3==(uint8_t)second.near&&globals.voice_25d6==(uint8_t)second.voice&&globals.combo_flag_9aa6==(uint8_t)second.combo_flag&&globals.combo_9aa8==second.combo_whole&&globals.combo_9aac==second.combo_fraction);
 apply_driver_state(&scene,&player,&runtime,&second);spawned=taxi_traffic_scene_update(actors,second.count,&scene);print_state(1,spawned,second.count,timer,counter,&globals,rng,&player,actors);
 taxi_world_asset_free(&world);taxi_traffic_grid_free(&grid);return 0;}
